namespace CSharpPracticum.Tasks.Level2;
internal abstract class Animal{public string Name{get;}protected Animal(string name)=>Name=name;public abstract string MakeSound();public override string ToString()=>Name;}
internal class Dog(string name):Animal(name){public override string MakeSound()=>"Гав";} internal class Cat(string name):Animal(name){public override string MakeSound()=>"Мяу";} internal class Bird(string name):Animal(name){public override string MakeSound()=>"Чирик";public string Fly()=>"летит";}
internal class Task24_Animals:ITask{public string Title=>"Задание 24: ООП Animal → Dog/Cat/Bird";public string Description=>"Построить иерархию животных и продемонстрировать полиморфизм.";public string[] Requirements=>new[]{"Абстрактный Animal с Name, MakeSound и ToString.","Dog, Cat и Bird реализуют MakeSound; Bird имеет Fly.","Вызвать звуки по List<Animal>."};public void Run(){List<Animal> animals=new(){new Dog("Бобик"),new Cat("Мурка"),new Bird("Кеша")};foreach(Animal a in animals)Console.WriteLine($"{a}: {a.MakeSound()}");Console.WriteLine(((Bird)animals[2]).Fly());}}
